        mock_fraud.return_value = VerificationStatus(status="REJECTED", details={"message": "Potential fraud detected"})
        result = self.validator.validate_transaction(self.transaction)
        self.assertEqual(result.status, "REJECTED")
        self.assertIn("fraud", str(result.details).lower())

    @patch.object(FraudDetector, 'verify')
