from __future__ import annotations
import os
import sys
import json
import logging
import time
import uuid
from datetime import datetime, timedelta
from dataclasses import dataclass
from typing import Any, Dict, Optional, List, Tuple
from abc import ABC, abstractmethod

# Optional dependency (kept optional to avoid import-time failures)
try:
    import toml  # type: ignore
except Exception:  # pragma: no cover - optional in audit environments
    toml = None  # noqa: N816


